(() => { const l = document.querySelector('#mensagens'); l.innerHTML = '';
  const add = s => l.append(html(s));
  add('<div class="msg-u">Faz o gancho com a reação surpresa, legenda no padrão e corta os melhores momentos</div>');
  add('<div class="msg-c"><p>Vou seguir a receita do gancho e a da legenda.</p></div>');
  add("<div class=\"passo ok\"><div class=\"cab\"><div class=\"ico\"><i data-i=\"file\"></i></div><div class=\"tit\"><b>Lendo a receita</b><span>receitas/1-gancho.md</span></div><div class=\"est\"><i data-i=\"check\"></i></div></div><div class=\"det\"></div></div>");
  add("<div class=\"passo ok\"><div class=\"cab\"><div class=\"ico\"><i data-i=\"terminal\"></i></div><div class=\"tit\"><b>Achando os melhores momentos</b><span>bo texto m1 --palavras</span></div><div class=\"est\"><i data-i=\"check\"></i></div></div><div class=\"det\"></div></div>");
  add("<div class=\"passo ok\"><div class=\"cab\"><div class=\"ico\"><i data-i=\"edit\"></i></div><div class=\"tit\"><b>Editando a linha do tempo</b><span>composicoes/comp1.json</span></div><div class=\"est\"><i data-i=\"check\"></i></div></div><div class=\"det\"></div></div>");
  add("<div class=\"passo ok\"><div class=\"cab\"><div class=\"ico\"><i data-i=\"captions\"></i></div><div class=\"tit\"><b>Ligando a legenda</b><span>Montserrat Bold · caixa azul</span></div><div class=\"est\"><i data-i=\"check\"></i></div></div><div class=\"det\"></div></div>");
  add("<div class=\"passo ok\"><div class=\"cab\"><div class=\"ico\"><i data-i=\"image\"></i></div><div class=\"tit\"><b>Renderizando um quadro</b><span>bo quadro 1.20</span></div><div class=\"est\"><i data-i=\"check\"></i></div></div><div class=\"det\"></div></div>");
  add('<div class="msg-c"><p>Pronto. O gancho abre com a <b>tela dividida</b> e a reação surpresa, o flash azul entra na volta e a legenda está no padrão Blue Ocean. Montei 3 cortes no ritmo da fala.</p></div>');
  document.querySelector('#entrada').value = ''; })()
